 return <main className={styles.workspace} data-study={params.get('study')||'strip'}><a href="#workspace-tools" className={styles.skipLink}>Skip to workspace tools</a><h1 className={styles.srOnly}>Dryspell geographic simulator</h1>
 <TerrainMap environment={environment} sensors={visibleSensors} ignitions={context==='simulation'?scenario?.ignitions||[]:[]} frame={context==='simulation'?frame:null} prediction={predictionQ.data} selected={selected} tool={tool} profile={profile} observations={markerReadings} satellites={context==='simulation'?[]:satelliteObservations} onSatelliteSelect={id=>{setSatelliteId(id);setSelected(null);setPanel('satellite');setTool('select');}} layers={{...layers,fire:context==='simulation'&&layers.fire,estimate:context==='simulation'&&layers.estimate}} proposed={proposed} onPoint={p=>void place(p)} onSelect={selectObject} onOverlap={ids=>{setOverlappingIds(ids);setSelected(null);setPanel('overlap');setTool('select');}} onUnavailable={setMapError}/>
 <header className={styles.contextControl}><button className={styles.brand} aria-label="Open workspace menu" onClick={()=>{setPanel(panel==='menu'?null:'menu');setSelected(null);}}><span className={styles.brandMark} aria-hidden="true">◈</span><span>Dryspell</span><Menu size={17} aria-hidden="true"/></button><label className={styles.contextLabel}><span className={styles.srOnly}>Workspace context</span><select aria-label="Workspace context" value={context} onChange={e=>setContext(e.target.value as Context)}><option value="simulation">{en.simulation}</option><option value="live">{en.live}</option><option value="history">{en.history}</option></select></label><button className={styles.scenarioName} onClick={()=>setPanel('menu')} title={scenario?.name}>{context==='simulation'?scenario?.name||'Loading landscape…':context==='live'?'Real sensor network':'Recorded observations'}<small>{context==='simulation'?`${environment?.sample?'Prepared sample · ':''}Revision ${scenario?.revision||'—'} · ${saving?'Saving…':pending?'Unsaved draft':scenario?.status||'loading'}`:socketState}</small></button></header>
 <div className={styles.environmentControl}>{weather&&<span className={styles.wind}><Wind size={18} aria-hidden="true"/><span>{weather.windSpeedMps.toFixed(1)} m/s<small>from {Math.round(weather.windFromDeg)}°</small></span></span>}<button aria-label="Map layers" aria-pressed={panel==='layers'} onClick={()=>{setPanel(panel==='layers'?null:'layers');setSelected(null);}}><Layers size={20} aria-hidden="true"/><span>Layers</span></button></div>
 <nav id="workspace-tools" className={styles.palette} aria-label="Object tools"><button aria-label="Select objects" title="Select (V)" aria-pressed={tool==='select'} onClick={()=>chooseTool('select')}><MousePointer2 size={22} aria-hidden="true"/><span>Select</span></button><button aria-label={en.tools.addSensor} disabled={!placementReady||saving} title={placementReady?`${en.tools.addSensor} (S)`:en.loadingEnvironment} aria-pressed={tool==='sensor'} onClick={()=>chooseTool('sensor')}><SensorSymbol profile={profile}/><span>{placementReady?en.tools.sensor:en.loading}</span></button>{context==='simulation'&&<button aria-label={en.tools.addIgnition} disabled={!placementReady||saving} title={placementReady?`${en.tools.addIgnition} (F)`:en.loadingEnvironment} aria-pressed={tool==='ignition'} onClick={()=>chooseTool('ignition')}><Flame size={23} aria-hidden="true"/><span>{placementReady?en.tools.ignition:en.loading}</span></button>}<button aria-label="Inspect terrain" title="Inspect terrain (T)" aria-pressed={tool==='terrain'} onClick={()=>chooseTool('terrain')}><Mountain size={23} aria-hidden="true"/><span>Terrain</span></button><div className={styles.toolDivider}/><button aria-label="Open sensor list" title="Sensors and filters" onClick={()=>{setPanel('sensors');setSelected(null);}}><List size={22} aria-hidden="true"/><span>Sensors</span></button></nav>
 {tool==='sensor'&&<div className={styles.profilePalette} role="group" aria-label="Sensor profile">{Object.values(SENSOR_PROFILES).map(p=><button key={p.id} aria-pressed={profile===p.id} onClick={()=>{setProfile(p.id);setNotice(`Place a ${p.name.toLowerCase()} sensor.`);}}><SensorSymbol profile={p.id}/><span>{p.name}</span></button>)}</div>}
 {tool!=='select'&&<div className={styles.placementHint}><span>{tool==='sensor'?`Place ${SENSOR_PROFILES[profile].name.toLowerCase()} sensor`:tool==='ignition'?'Place ignition':tool==='terrain'?'Inspect effective terrain':'Choose proposed location'}</span><button onClick={()=>setPanel('coordinates')}><MapPin size={16} aria-hidden="true"/>Coordinates</button><button aria-label="Cancel placement" onClick={()=>{setTool('select');setProposed(null);}}><X size={18} aria-hidden="true"/></button></div>}
 {(error||pending||mapError||workspaceQ.isError||scenariosQ.isError)&&<div className={styles.errorBanner} role="alert"><TriangleAlert size={18} aria-hidden="true"/><span>{error||mapError||(workspaceQ.error||scenariosQ.error)?.message||'An edit is waiting to save.'}</span>{pending&&<button onClick={()=>void patchScenario(pending)}>Retry save</button>}{pending&&<button onClick={()=>{setPending(null);setError('');}}>Discard draft</button>}{!pending&&<button onClick={()=>{setError('');refresh();}}>Retry</button>}</div>}
 {notice&&!error&&<div className={styles.notice} role="status">{notice}<button aria-label="Dismiss notice" onClick={()=>setNotice('')}><X size={14} aria-hidden="true"/></button></div>}
 {(!scenario||!placementReady)&&!workspaceQ.isError&&!scenariosQ.isError&&<div className={styles.loading}>{en.loadingWorkspace}</div>}
 {panel&&<aside className={`${styles.inspector} ${expanded?styles.expanded:''}`} aria-label={panelTitle}><div className={styles.panelHeader}><h2>{panelTitle}</h2><div><button className={styles.expandButton} aria-label={expanded?'Collapse inspector':'Expand inspector'} onClick={()=>setExpanded(!expanded)}>{expanded?<ChevronDown size={20}/>:<ChevronUp size={20}/>}</button><button aria-label="Close inspector" onClick={closePanel}><X size={20} aria-hidden="true"/></button></div></div><div className={styles.panelBody}>
 {panel==='satellite'&&<>{satellite?<><div className={styles.objectIdentity}><span className={styles.satelliteGlyph} aria-hidden="true">◇</span><div>{satellite.instrument}<small>Satellite hotspot observation</small></div></div><dl className={styles.propertyList}><dt>Observed</dt><dd>{timestamp(satellite.observedAt)}</dd><dt>Received</dt><dd>{timestamp(satellite.receivedAt)}</dd><dt>Nominal resolution</dt><dd>{satellite.nominalResolutionM} m</dd><dt>Provider confidence</dt><dd>{satellite.confidence}</dd><dt>Coordinates</dt><dd>{satellite.location.latitude.toFixed(5)}, {satellite.location.longitude.toFixed(5)}</dd></dl><p>A hotspot is a coarse satellite detection, not an exact perimeter. Provider confidence is not a calibrated wildfire probability. Missing detections do not establish no fire.</p></>:<p>No matching satellite observation at this cursor.</p>}<button onClick={()=>setPanel('layers')}>Back to layers</button></>}
 {panel==='overlap'&&<><p>{en.chooseObject}</p><div className={styles.overlapList}>{overlappingIds.map(id=>{const object=allSensors.find(s=>s.id===id);const fire=scenario?.ignitions.find(i=>i.id===id);return object?<button key={id} onClick={()=>selectObject(id)}><SensorSymbol profile={object.profileId}/><span>{object.name}<small>{SENSOR_PROFILES[object.profileId].name} · {object.deviceId}</small></span></button>:fire?<button key={id} onClick={()=>selectObject(id)}><Flame size={22} aria-hidden="true"/><span>Ignition<small>{fire.timeSec} simulation seconds · {id.slice(0,8)}</small></span></button>:null;})}</div></>}
 {panel==='sensor'&&sensor&&<><div className={styles.objectIdentity}><SensorSymbol profile={sensor.profileId} size={34}/><div>{SENSOR_PROFILES[sensor.profileId].name} sensor<small>{sensor.source==='simulated'?'Simulated observation':'Real device'} · {sensor.enabled?'Enabled':'Disabled'}</small></div></div>{context==='live'&&sensorHealth&&<p className={styles.deviceHealth}><span>Connection: {sensorHealth.state}</span><small>Evaluated {timestamp(sensorHealth.evaluatedAt)}. Device health is separate from fire evidence.</small></p>}<p className={styles.coordinates}>{sensor.location.latitude.toFixed(6)}, {sensor.location.longitude.toFixed(6)}</p>{!visibleSensors.some(s=>s.id===sensor.id)&&<p className={styles.warning}>This sensor is hidden by the current map filter.</p>}<div className={styles.readings}>{(['temperatureC','humidityPct','smokePct'] as Channel[]).map(channel=>{const reading=readingState(sensor,observation,channel,selectedTime);return <div key={channel} data-channel={channel}><span>{channelNames[channel]}</span><strong>{'value' in reading?reading.value.toFixed(1):'—'}</strong><small>{reading.state==='unsupported'?en.readings.unsupported:reading.state==='missing'?en.readings.missing:`${reading.unit}${reading.state==='stale'?' · Stale':''}`}</small></div>;})}</div><p className={styles.caption}>{observation?`Observed ${timestamp(observation.recordedAt,scenario?.config.timeZone)}`:'No observation at the selected time.'}</p>{observation?.quality.length? <p className={styles.warning}>Quality: {observation.quality.join(', ')}</p>:null}<Suspense fallback={<p className={styles.caption}>Loading measurement charts…</p>}><TelemetryCharts sensor={sensor} readings={readings} at={selectedTime} baseline={weather?.temperatureC} timeZone={context==='simulation'?scenario?.config.timeZone:'UTC'} loading={context==='simulation'?readingsQ.isFetching:realReadingsQ.isFetching} historyError={(context==='simulation'?readingsQ.error:realReadingsQ.error)?.message}/></Suspense>{context==='simulation'&&scenario&&<SensorFaultSettings key={`${sensor.id}:${scenario.revision}`} sensor={sensor} durationSec={scenario.config.durationSec} saving={saving} onSave={faults=>patchScenario({sensors:scenario.sensors.map(s=>s.id===sensor.id?{...s,simulationFaults:faults}:s)})}/>}<details><summary>Metadata and configuration</summary><form onSubmit={async e=>{e.preventDefault();if(!requireAdmin())return;const data=new FormData(e.currentTarget);const patch={name:String(data.get('name')),enabled:data.get('enabled')==='on',expectedIntervalSec:Number(data.get('interval')),tags:String(data.get('tags')).split(',').map(s=>s.trim()).filter(Boolean)};if(context==='simulation')await patchScenario({sensors:scenario!.sensors.map(s=>s.id===sensor.id?{...s,...patch}:s)});else try{await api(`/sensors/${sensor.id}`,{method:'PATCH',body:JSON.stringify(patch)});refresh();}catch(e){setError((e as Error).message);}}} key={sensor.id+sensor.updatedAt}><label>Name<input name="name" defaultValue={sensor.name} required maxLength={120}/></label><label>Expected interval (seconds)<input name="interval" type="number" min="1" defaultValue={sensor.expectedIntervalSec} required/></label><label className={styles.check}><input name="enabled" type="checkbox" defaultChecked={sensor.enabled}/>Device enabled</label><label>Tags (comma separated)<input name="tags" defaultValue={sensor.tags.join(', ')}/></label><p className={styles.caption}>Device ID: {sensor.deviceId}</p><button type="submit" disabled={saving}><Save size={16} aria-hidden="true"/>Save metadata</button></form></details>{context!=='simulation'&&<details><summary>Device access and data retention</summary><p className={styles.caption}>Ingestion credentials are separate from administrator access and scoped to this device.</p><button onClick={async()=>{if(!requireAdmin())return;try{setCredential(await api<{id:string;token:string}>(`/sensors/${sensor.id}/credentials`,{method:'POST',body:'{}'}));}catch(e){setError((e as Error).message);}}}>Issue ingestion credential</button>{credential&&<><label>New token (shown only in this session)<textarea readOnly rows={3} value={credential.token}/></label><button onClick={async()=>{try{await api(`/credentials/${credential.id}`,{method:'DELETE'});setCredential(null);setNotice('Credential revoked.');}catch(e){setError((e as Error).message);}}}>Revoke this credential</button></>}<button onClick={async()=>{if(!requireAdmin())return;if(!confirm(`Archive ${sensor.name} and review its permanent deletion count?`))return;try{const result=await api<{affectedRecords:number}>(`/sensors/${sensor.id}`,{method:'DELETE'});refresh();const typed=prompt(`This will permanently delete ${result.affectedRecords} observations for ${sensor.deviceId}. Type the device ID to delete permanently, or cancel to retain the archive.`);if(typed===sensor.deviceId){await api(`/sensors/${sensor.id}?permanent=true`,{method:'DELETE',body:JSON.stringify({confirmDeviceId:typed,affectedRecords:result.affectedRecords})});closePanel();refresh();}}catch(e){setError((e as Error).message);}}}>Archive and review permanent deletion</button></details>}<div className={styles.actions}><button onClick={()=>chooseTool('move')}><Move size={17} aria-hidden="true"/>Move</button><button onClick={()=>{setTool('move');setProposed(sensor.location);setPanel('coordinates');}}><MapPin size={17} aria-hidden="true"/>Coordinates</button><button onClick={async()=>{if(!requireAdmin())return;if(context==='simulation'){await patchScenario({sensors:scenario!.sensors.filter(s=>s.id!==sensor.id)});closePanel();}else{try{await api(`/sensors/${sensor.id}`,{method:'PATCH',body:JSON.stringify({archived:!sensor.archived,enabled:sensor.archived})});refresh();}catch(e){setError((e as Error).message);}}}}><Trash2 size={17} aria-hidden="true"/>{context==='simulation'?'Remove (undoable)':sensor.archived?'Restore':'Archive'}</button></div></>}
 {panel==='ignition'&&ignition&&<><div className={styles.objectIdentity}><Flame size={30} aria-hidden="true"/><div>Simulated ignition<small>Ground truth, never inference input</small></div></div><p>{ignition.location.latitude.toFixed(6)}, {ignition.location.longitude.toFixed(6)}</p><form key={ignition.id} onSubmit={async e=>{e.preventDefault();const timeSec=Number(new FormData(e.currentTarget).get('timeSec'));await patchScenario({ignitions:scenario!.ignitions.map(i=>i.id===ignition.id?{...i,timeSec}:i)});}}><label>Ignition time (simulation seconds)<input name="timeSec" type="number" min="0" max={scenario?.config.durationSec} defaultValue={ignition.timeSec}/></label><button type="submit">Save ignition time</button></form><div className={styles.actions}><button onClick={()=>chooseTool('move')}><Move size={16} aria-hidden="true"/>Move</button><button onClick={async()=>{await patchScenario({ignitions:scenario!.ignitions.filter(i=>i.id!==ignition.id)});closePanel();}}>Remove (undoable)</button></div></>}
 {proposed&&tool==='move'&&<div className={styles.proposed}><strong>Proposed position</strong><p>{proposed.latitude.toFixed(6)}, {proposed.longitude.toFixed(6)}</p><button onClick={()=>void saveMove()} disabled={saving}>Save movement</button><button onClick={()=>{setProposed(null);setTool('select');}}>Cancel movement</button></div>}
 {panel==='terrain'&&environment&&<>{terrain?<><div className={styles.terrainSwatch} data-cover={terrain.cover}><Mountain size={28} aria-hidden="true"/><strong>{terrain.cover}</strong><span>{terrain.burnable?'Burnable fuel':'Non-burnable'}</span></div><dl className={styles.propertyList}><dt>Elevation</dt><dd>{terrain.elevationM===null?'Unknown':`${terrain.elevationM.toFixed(1)} m`}</dd><dt>Slope</dt><dd>{terrain.slopeDeg===null?'Unknown':`${terrain.slopeDeg.toFixed(1)}°`}</dd><dt>Aspect</dt><dd>{terrain.aspectDeg===null?'Unknown':`${terrain.aspectDeg.toFixed(0)}°`}</dd><dt>Fuel assumption</dt><dd>{terrain.fuelModel}</dd><dt>Baseline spread</dt><dd>{terrain.spreadRateMps.toFixed(3)} m/s</dd><dt>Moisture</dt><dd>{terrain.moisture.toFixed(2)}</dd><dt>Grid resolution</dt><dd>{environment.landscape.cellSizeM} m</dd><dt>Cell</dt><dd>{terrainIndex}</dd></dl><p className={styles.caption}>This is the effective grid used by the engine. Basemap appearance does not change these values.</p></>:<p>Choose a point inside the prepared area.</p>}<details open><summary>Input identity</summary><p className={styles.code}>{environment.id}</p><p className={styles.caption}>Landscape: {environment.landscape.id}<br/>Valid: {timestamp(environment.weather.validAt)}</p>{environment.warnings.map(w=><p key={w} className={styles.warning}>{w}</p>)}</details>{terrain&&scenario&&context==='simulation'&&<details><summary>Scenario fuel override</summary><p className={styles.caption}>Changes this effective cell in a new immutable snapshot. It creates a new draft revision.</p><form key={environment.id+terrainIndex} onSubmit={async e=>{e.preventDefault();if(!requireAdmin())return;const d=new FormData(e.currentTarget);try{await api(`/scenarios/${scenario.id}/inputs`,{method:'POST',body:JSON.stringify({revision:scenario.revision,fuelOverrides:[{cell:terrainIndex,spreadRateMps:Number(d.get('spread')),moisture:Number(d.get('moisture')),burnable:d.get('burnable')==='on'}]})});refresh();setNotice('Fuel override saved as a new draft.');}catch(e){setError((e as Error).message);}}}><label>Baseline spread (m/s)<input name="spread" type="number" min="0" max="10" step="0.001" defaultValue={terrain.spreadRateMps} required/></label><label>Moisture fraction<input name="moisture" type="number" min="0" max="1" step="0.01" defaultValue={terrain.moisture} required/></label><label className={styles.check}><input name="burnable" type="checkbox" defaultChecked={terrain.burnable}/>Burnable in this experiment</label><button type="submit">Save fuel override</button></form></details>}</>}
 {panel==='sensors'&&<><label>Profile<select value={profileFilter} onChange={e=>setProfileFilter(e.target.value)}><option value="all">All profiles</option>{Object.values(SENSOR_PROFILES).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><details><summary>Advanced filters ({[filter,profileFilter!=='all',freshnessFilter!=='all',coverFilter!=='all',rangeMin,rangeMax].filter(Boolean).length})</summary><label>Device freshness<select value={freshnessFilter} onChange={e=>setFreshnessFilter(e.target.value)}><option value="all">All states</option><option value="fresh">Recent reading</option><option value="stale">Stale or missing reading</option><option value="disabled">Disabled devices</option></select></label><label>Effective land cover<select value={coverFilter} onChange={e=>setCoverFilter(e.target.value)}><option value="all">All terrain</option>{['grass','woodland','scrub','water','built','unknown'].map(c=><option key={c} value={c}>{c}</option>)}</select></label><label>Measurement range<select value={rangeChannel} onChange={e=>setRangeChannel(e.target.value as Channel)}>{Object.entries(channelNames).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><div className={styles.rangeInputs}><label>Minimum<input type="number" step="any" value={rangeMin} onChange={e=>setRangeMin(e.target.value)}/></label><label>Maximum<input type="number" step="any" value={rangeMax} onChange={e=>setRangeMax(e.target.value)}/></label></div><button onClick={()=>{setFilter('');setProfileFilter('all');setFreshnessFilter('all');setCoverFilter('all');setRangeMin('');setRangeMax('');}}>Clear all filters</button></details><SensorList sensors={visibleSensors} statuses={context==='live'?sensorStatusQ.data:undefined} onSelect={selectObject} filter={filter} onFilter={setFilter}/><button onClick={()=>{chooseTool('sensor');setPanel('coordinates');}}><Plus size={16} aria-hidden="true"/>Add by coordinates</button>{mapError&&<p className={styles.warning}>The sensor list and numeric placement remain available while the map is unavailable.</p>}</>}
 {panel==='coordinates'&&<form onSubmit={async e=>{e.preventDefault();const d=new FormData(e.currentTarget);const p={latitude:Number(d.get('latitude')),longitude:Number(d.get('longitude'))};if(context!=='simulation'&&tool==='sensor'){if(!requireAdmin())return;try{await api('/sensors',{method:'POST',body:JSON.stringify({deviceId:d.get('deviceId'),name:d.get('name'),source:'real',location:p,profileId:profile,capabilities:SENSOR_PROFILES[profile].capabilities,expectedIntervalSec:60,enabled:true,tags:[]})});refresh();setPanel('sensors');setTool('select');}catch(e){setError((e as Error).message);}}else await place(p);}}><p>{tool==='terrain'?'Inspect the selected ground without using the map.':tool==='move'?'Enter the proposed position, then Save movement.':'Place an object without using the map.'}</p>{tool==='select'&&<label>Object<select onChange={e=>setTool(e.target.value as Tool)} defaultValue="select"><option value="select">Choose a tool</option><option value="sensor">Sensor</option><option value="ignition">Ignition</option><option value="terrain">Terrain point</option></select></label>}{tool==='sensor'&&<label>Sensor profile<select value={profile} onChange={e=>setProfile(e.target.value as ProfileId)}>{Object.values(SENSOR_PROFILES).map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label>}<label>Latitude<input name="latitude" type="number" step="any" min="-90" max="90" defaultValue={proposed?.latitude??sensor?.location.latitude??environment?.landscape.origin.latitude??53.025} required/></label><label>Longitude<input name="longitude" type="number" step="any" min="-180" max="180" defaultValue={proposed?.longitude??sensor?.location.longitude??environment?.landscape.origin.longitude??-6.3515} required/></label>{context!=='simulation'&&tool==='sensor'&&<><label>Device ID<input name="deviceId" required autoComplete="off"/></label><label>Display name<input name="name" required/></label></>}<button type="submit" className={styles.primary} disabled={saving||!placementReady||tool==='select'}>{!placementReady?en.loading:tool==='move'?en.previewPosition:tool==='terrain'?en.tools.inspectTerrain:en.placeObject}</button><button type="button" onClick={()=>{setTool('select');setPanel(null);setProposed(null);}}>Cancel</button></form>}
 {panel==='layers'&&<><p className={styles.caption}>These controls change presentation only.</p><label className={styles.check}><input type="checkbox" checked={layers.landscape} onChange={e=>setLayers(l=>({...l,landscape:e.target.checked}))}/>Effective land cover</label><label className={styles.check}><input type="checkbox" checked={layers.relief} onChange={e=>setLayers(l=>({...l,relief:e.target.checked}))}/>Numerical relief shading</label>{context!=='simulation'&&<><label className={styles.check}><input type="checkbox" checked={!!layers.satellite} onChange={e=>{setLayers(l=>({...l,satellite:e.target.checked}));setSatellitePage(0);}}/>Satellite hotspot observations</label>{layers.satellite&&<><p className={styles.caption}>Detections in the previous 24 hours, known at the selected time. Coarse point symbols identify observations; they do not trace a perimeter or encode fire probability.</p>{firmsStatus?.status==='unavailable'&&<p className={styles.warning}>NASA FIRMS live source unavailable. A configured data connection is required. Previously imported observations remain inspectable.</p>}{satelliteQ.isError&&<p role="alert" className={styles.warning}>{satelliteQ.error.message}</p>}{satelliteQ.isFetching?<p className={styles.caption}>Loading satellite observations…</p>:!satelliteObservations.length?<p className={styles.caption}>No imported satellite observations in this area and time window.</p>:<details><summary>Inspect {satelliteObservations.length} observations</summary><div className={styles.satelliteList}>{satelliteObservations.slice(satellitePage*50,(satellitePage+1)*50).map(o=><button key={o.id} onClick={()=>{setSatelliteId(o.id);setPanel('satellite');}}><span>◇ {o.instrument}<small>{timestamp(o.observedAt)} · {o.nominalResolutionM} m nominal</small></span></button>)}</div><div className={styles.actions}><button disabled={satellitePage===0} onClick={()=>setSatellitePage(p=>p-1)}>Previous observations</button><button disabled={(satellitePage+1)*50>=satelliteObservations.length} onClick={()=>setSatellitePage(p=>p+1)}>Next observations</button></div></details>}</>}</>}{context==='simulation'&&<><div className={styles.segmented} aria-label="Fire and estimate comparison">{['Fire','Estimate','Compare'].map(mode=><button key={mode} aria-pressed={mode==='Fire'?layers.fire&&!layers.estimate:mode==='Estimate'?!layers.fire&&layers.estimate:layers.fire&&layers.estimate} onClick={()=>setLayers(l=>({...l,fire:mode!=='Estimate',estimate:mode!=='Fire'}))}>{mode}</button>)}</div>{layers.estimate&&<><p>Estimated current burning. Fixed probability scale; this is not simulated truth.</p><div className={styles.probabilityLegend}><span>0%</span><i/><span>100%</span></div><p className={styles.caption}>{predictionQ.data?`Issued ${timestamp(predictionQ.data.issuedAt)} · ${predictionQ.data.calibrationStatus}`:predictionQ.isFetching?'Loading matching estimate…':'No estimate exists for this frame.'}</p><button disabled={requestingPrediction||!frame} onClick={async()=>{if(!requireAdmin()||!environment||!frame||!scenario)return;setRequestingPrediction(true);try{await api('/predictions',{method:'POST',body:JSON.stringify({scenarioId:scenario.id,revision:scenario.revision,at:frame.timeSec})});setNotice('Estimate queued. Inputs contain observations and environment only.');client.invalidateQueries({queryKey:['prediction']});}catch(e){setError((e as Error).message);}finally{setRequestingPrediction(false);}}}>{requestingPrediction?'Queuing…':'Estimate from observations'}</button></>}</>}<div className={styles.landCoverLegend}>{['woodland','grass','scrub','water','unknown'].map(c=><span key={c}><i data-cover={c}/>{c}</span>)}</div><button onClick={()=>setPanel('sources')}>Inspect source data</button></>}
 {panel==='menu'&&<><h3>Saved scenarios</h3><div className={styles.scenarioList}>{scenarios.map(s=><button key={s.id} aria-pressed={s.id===scenarioId} onClick={()=>{setScenarioId(s.id);setContext('simulation');setPanel(null);setSelected(null);setUndo([]);}}><span>{s.name}<small>Revision {s.revision} · {s.status}</small></span><ChevronDown size={16} aria-hidden="true"/></button>)}</div><div className={styles.actions}><button onClick={async()=>{if(!requireAdmin())return;try{const s=await api<Scenario>('/scenarios',{method:'POST',body:JSON.stringify({name:`Landscape study ${scenarios.length+1}`,sensors:[],ignitions:[]})});setScenarioId(s.id);setContext('simulation');setPanel(null);refresh();}catch(e){setError((e as Error).message);}}}><Plus size={16} aria-hidden="true"/>New blank scenario</button><button onClick={async()=>{if(!scenario||!requireAdmin())return;try{const s=await api<Scenario>(`/scenarios/${scenario.id}/clone`,{method:'POST',body:'{}'});setScenarioId(s.id);refresh();}catch(e){setError((e as Error).message);}}}><Copy size={16} aria-hidden="true"/>Clone</button></div><div className={styles.menuItems}>{context==='simulation'&&<button onClick={()=>{setFollow(true);setPlaying(false);setPanel(null);client.invalidateQueries({queryKey:['workspace',scenarioId]});}}><LocateFixed size={18} aria-hidden="true"/>Follow authoritative run</button>}<button onClick={()=>setPanel('sensors')}><List size={18} aria-hidden="true"/>Sensors and filters</button><button onClick={()=>setPanel('incidents')}><TriangleAlert size={18} aria-hidden="true"/>Incidents</button><button onClick={()=>setPanel('settings')}><Settings size={18} aria-hidden="true"/>Scenario settings</button><button onClick={()=>setPanel('sources')}><Info size={18} aria-hidden="true"/>Sources and model limits</button></div><div className={styles.account}>{session?.authenticated?<><span>Signed in as {session.username}</span><button onClick={async()=>{try{await api('/auth/logout',{method:'POST',body:'{}'});setSession({authenticated:false});client.invalidateQueries({queryKey:['session']});}catch(e){setError((e as Error).message);}}}><LogOut size={17} aria-hidden="true"/>Sign out</button></>:<><p>Anyone can inspect and replay. Sign in to place objects or save changes.</p><button onClick={()=>setLoginOpen(true)}><LogIn size={17} aria-hidden="true"/>Administrator sign in</button></>}</div><p className={styles.caption}>Keyboard: V select, S sensor, F fire, T terrain. Escape cancels placement.</p></>}
 {panel==='settings'&&scenario&&<><form key={scenario.id+scenario.revision} onSubmit={async e=>{e.preventDefault();const d=new FormData(e.currentTarget);await patchScenario({name:String(d.get('name')),seed:Number(d.get('seed')),config:{...scenario.config,durationSec:Number(d.get('duration')),timeZone:String(d.get('zone'))}});}}><label>Scenario name<input name="name" defaultValue={scenario.name} required maxLength={120}/></label><label>Duration (seconds)<input name="duration" type="number" min="60" max="86400" step="5" defaultValue={scenario.config.durationSec}/></label><label>Random seed<input name="seed" type="number" defaultValue={scenario.seed}/></label><label>Display time zone<input name="zone" defaultValue={scenario.config.timeZone}/></label><p className={styles.caption}>Editing a scenario after results exist creates a new draft revision. Previous results stay attached to their original input version.</p><button type="submit" disabled={saving}>Save settings</button><dl className={styles.propertyList}><dt>Sample interval</dt><dd>{scenario.config.outputIntervalSec} s</dd><dt>Checkpoint interval</dt><dd>{scenario.config.checkpointIntervalSec} s</dd><dt>Sensor response radius</dt><dd>{scenario.config.responseRadiusM} m</dd></dl></form><EnvironmentSettings scenario={scenario} environment={environment} requireAdmin={requireAdmin} onEnvironment={id=>patchScenario({environmentId:id})} onSaved={refresh} onError={setError}/></>}
 {panel==='sources'&&environment&&<><p>{environment.name}</p><p className={styles.caption}>{environment.sample?'Prepared sample data':'Provider environment'} · {environment.status}</p><p className={styles.code}>{environment.id}</p>{[...environment.landscape.provenance,...environment.weather.provenance].map((p,i)=><section key={i} className={styles.provenance}><h3>{p.provider}</h3><p>{p.attribution}</p><a href={p.sourceUrl} target="_blank" rel="noreferrer">Source documentation</a><p className={styles.caption}>{p.license}<br/>Version {p.version}<br/>Valid {timestamp(p.validAt)}<br/>{p.resolutionM?`${p.resolutionM} m source resolution`:''}</p></section>)}{environment.warnings.map(w=><p className={styles.warning} key={w}>{w}</p>)}<h3>Model limits</h3><p>Surface-fire simulation is an experimental baseline. Smoke is a normalized sensor response, not pollutant concentration. Estimates are uncalibrated unless explicitly labelled otherwise; a critical 70 °C reading does not independently confirm a wildfire.</p><details><summary>Provider diagnostics</summary><pre>{JSON.stringify(sourcesQ.data,null,2)}</pre></details></>}
 {panel==='incidents'&&<>{incidentsQ.isLoading?<p>Loading incidents…</p>:!incidentsQ.data?.length?<p>No incidents in this context.</p>:incidentsQ.data.map(i=><section key={i.id} className={styles.incident}><strong>{i.state}</strong><p>{i.sensorId}</p><p className={styles.caption}>{timestamp(i.observedAt)}</p><p>{i.evidence.join('; ')}</p><button onClick={async()=>{if(!requireAdmin())return;try{await api(`/incidents/${i.id}/acknowledge`,{method:'POST',body:'{}'});client.invalidateQueries({queryKey:['incidents']});}catch(e){setError((e as Error).message);}}}>Acknowledge</button><button onClick={async()=>{if(!requireAdmin())return;if(!confirm('Record manual wildfire confirmation for this incident?'))return;try{await api(`/incidents/${i.id}/confirm`,{method:'POST',body:'{}'});client.invalidateQueries({queryKey:['incidents']});}catch(e){setError((e as Error).message);}}}>Confirm manually</button></section>)}</>}
 </div></aside>}
 <div className={styles.mapLegend}>{context==='simulation'&&<><span><i className={styles.activeFire}/>Active fire</span><span><i className={styles.burned}/>Burned ground</span></>}{context!=='simulation'&&layers.satellite&&<span>◇ Satellite detections</span>}<span className={styles.sampleLabel}>{environment?.sample?'Prepared landscape sample':environment?.name||'Loading environment'}</span></div>
 <footer className={styles.transport} aria-label="Time controls">{context==='simulation'?<><div className={styles.runGroup}><button className={styles.runButton} disabled={saving||!scenario||environment?.status==='unavailable'||environment?.status==='preparing'||(!scenario?.ignitions.length&&scenario?.status!=='running')} onClick={()=>void action(scenario?.status==='running'?'pause':'run')}>{scenario?.status==='running'?<Pause size={18} aria-hidden="true"/>:<Flame size={18} aria-hidden="true"/>}<span>{scenario?.status==='running'?en.time.pauseRun:en.time.run}</span></button><button aria-label="Undo last edit" title="Undo last saved edit" disabled={!undo.length||saving} onClick={async()=>{const old=undo.at(-1);if(old&&await patchScenario({sensors:old.sensors,ignitions:old.ignitions,config:old.config},false))setUndo(v=>v.slice(0,-1));}}><Undo2 size={17} aria-hidden="true"/></button></div><div className={styles.replayGroup}><button aria-label={en.time.rewind} onClick={()=>seek(0)} disabled={!latestTime}><SkipBack size={18} aria-hidden="true"/></button><button aria-label={playing?en.time.pauseReplay:en.time.playReplay} disabled={!latestTime} onClick={()=>{setFollow(false);if(cursor>=latestTime)setCursor(0);setPlaying(!playing);}}>{playing?<Pause size={18} aria-hidden="true"/>:<Play size={18} aria-hidden="true"/>}</button><button aria-label={en.time.step} disabled={!latestTime} onClick={()=>seek(cursor+5)}><StepForward size={18} aria-hidden="true"/></button></div><div className={styles.timeRail}><div><strong>{duration(cursor)}</strong><span>{stateQ.isFetching?'Seeking…':follow?'Following run':'Replay'} · {timestamp(selectedTime,scenario?.config.timeZone)}</span></div><input aria-label="Simulation time" type="range" min="0" max={Math.max(5,latestTime)} step="5" value={Math.min(cursor,Math.max(5,latestTime))} onChange={e=>seek(Number(e.target.value))} disabled={!latestTime}/><div className={styles.timeTicks}><span>Start</span><span>{duration(latestTime)} recorded</span></div></div><label className={styles.speed}><span>Replay speed</span><select aria-label={en.time.replaySpeed} value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value={1}>1×</option><option value={10}>10×</option><option value={60}>60×</option></select></label><button className={styles.followButton} aria-pressed={follow} onClick={()=>{setFollow(true);setPlaying(false);client.invalidateQueries({queryKey:['workspace',scenarioId]});}}><LocateFixed size={17} aria-hidden="true"/><span>Follow run</span></button></>:<><div className={styles.liveLabel}><Radio size={20} aria-hidden="true"/><strong>{context==='live'?'Live observations':'History cursor'}</strong><small>{socketState}</small></div><label className={styles.historyInput}>Selected time (UTC)<input type="datetime-local" aria-label="History selected time" value={historyDraft||historyAt.slice(0,16)} onChange={e=>setHistoryDraft(e.target.value)}/></label><button onClick={()=>{if(historyDraft){setHistoryAt(new Date(historyDraft+'Z').toISOString());setContext('history');}}}>Inspect time</button><button onClick={()=>{setContext('live');setHistoryAt(new Date().toISOString());setHistoryDraft('');}}>Return to live</button></>}</footer>
 <Dialog.Root open={loginOpen} onOpenChange={setLoginOpen}><Dialog.Portal><Dialog.Overlay className={styles.dialogOverlay}/><Dialog.Content className={styles.dialog}><Dialog.Title>Administrator sign in</Dialog.Title><Dialog.Description>Sign in to place objects and save changes. Public replay remains available.</Dialog.Description><form onSubmit={async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setLoginError('');const d=new FormData(e.currentTarget);try{const s=await api<SessionInfo>('/auth/login',{method:'POST',body:JSON.stringify({username:d.get('username'),password:d.get('password')})});setSession(s);client.setQueryData(['session'],s);setLoginOpen(false);setNotice('Signed in. Choose a tool to start placing objects.');}catch(e){setLoginError((e as Error).message);}}}><label>Username<input name="username" autoComplete="username" required/></label><label>Password<input name="password" type="password" autoComplete="current-password" required/></label>{loginError&&<p role="alert" className={styles.warning}>{loginError}</p>}<button className={styles.primary} type="submit">Sign in</button></form><Dialog.Close className={styles.dialogClose} aria-label="Close sign in"><X size={20} aria-hidden="true"/></Dialog.Close></Dialog.Content></Dialog.Portal></Dialog.Root>
 </main>;
